          "detailMarkdown": "## 3518 柏騰 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026Q1 合併營收 **62 百萬元**，較 2025Q4 的 76 百萬元與 2025Q1 的 74 百萬元下滑。\n- 2026Q1 合併稅後淨利 **283 百萬元**，每股盈餘 **2.81 元**；主要受 **子公司股權交易收益** 與 **金融資產評價利益** 影響。\n- 2026/3/31 資產總計 **2,443 百萬元**，權益總計 **1,703 百萬元**，每股淨值 **16.60 元**。\n- 2026Q1 負債比率 **30.28%**，流動比率 **400.58%**，現金及約當現金 **661 百萬元**。\n- Q1 現金流量中，營業活動淨現金流入 **71 百萬元**，期末現金較期初增加至 **661 百萬元**。\n\n### 展望與成長利基\n- EMI 鍍膜業務方面，管理層表示 **下半年仍面臨營收衰退壓力**，主因為 NB 市場不佳與成本上升。\n- SiC 業務方面，**8 吋導電型產品已開始小批量出貨**，並提及 2026 年下半年 SiC 產品營收占比有機會達 **5%～10%**。\n- 公司持續推進 **SiC 散熱基板** 與 **6/8 吋加工、再生服務**，並規劃與 PVD 技術整合，強調附加價值。\n- 產品應用方向聚焦於 **AI 高功率散熱、電動車、儲能/綠能、衛星/雷達、軍工** 等需求。\n- 管理層提到，隨著 2027 年後量產需求增加，SiC 相關需求可能進一步升溫。\n\n### 產品、客戶與市場位置\n- 公司主軸仍為 **PVD 真空鍍膜** 與 **SiC 碳化矽材料** 雙線發展，並持續由傳統 EMI/ESD 應用轉向半導體先進製程與散熱應用。\n- 本次說明重點集中在 **嘉義 SiC 新廠進度**、產品驗證與營運轉型方向。\n- 管理層提到，**中國區部分 PVD 產線已移回台灣**，研發重心也回到台灣，配合客戶開發先進製程技術。\n- 2026 年上半年 EMI 鍍膜產品營收受 NB 市況與主要客戶接單影響，整體仍偏弱。\n- SiC 產品已開始小量出貨，後續以 8 吋導電型與散熱基板為主要發展方向。\n- EMI 鍍膜業務方面，管理層表示 **下半年仍面臨營收衰退壓力**，主因為 NB 市場不佳與成本上升。\n\n### 風險與不確定性\n- 嘉義新廠仍有部分 **環評申請審核中**，工廠登記證預計 **2026Q4** 取得，全面量產時程延後至 **2027Q1**。\n- 因尚未完成廢水排放條件，部分製程（如後段拋光與清洗）受限，短期仍需依賴 **委外加工**。\n- EMI 鍍膜業務受 **NB 需求疲弱、客戶接單變動、成本壓力** 影響，營收下滑風險仍在。\n- SiC 業務仍處於 **試產、驗證與爬坡階段**，量產節奏與客戶驗證進度存在不確定性。\n- 財報中業外收益占比高，後續獲利表現可能與本業營運狀況存在落差。\n- **需人工確認：2025 年度與 2026Q1 EPS 數字敘述不一致**\n- 簡報第 14 頁提到：115 年度第一季基本每股盈餘 **2.85 元**。\n- 簡報第 11 頁 Q1 財報表列示 EPS **2.81 元**。\n\n### Q&A 與管理層口氣\n- Q：SiC 下半年是否可占營收 5%～10%？\n- Q：SiC 後段加工合作夥伴是台廠或海外？\n- Q：SiC 毛利率/獲利貢獻水準？\n- Q：國外大廠驗證案是散熱還是導電？\n- 會中亦提及公司將持續透過客戶驗證、備貨與小批量出貨方式推進 SiC 業務。\n\n### 評分利基點\n- 加分主因：公司持續推進 **SiC 散熱基板** 與 **6/8 吋加工、再生服務**，並規劃與 PVD 技術整合，強調附加價值。；產品應用方向聚焦於 **AI 高功率散熱、電動車、儲能/綠能、衛星/雷達、軍工** 等需求。；管理層提到，隨著 2027 年後量產需求增加，SiC 相關需求可能進一步升溫。。\n- 扣分或保留：嘉義新廠仍有部分 **環評申請審核中**，工廠登記證預計 **2026Q4** 取得，全面量產時程延後至 **2027Q1**。；因尚未完成廢水排放條件，部分製程（如後段拋光與清洗）受限，短期仍需依賴 **委外加工**。；EMI 鍍膜業務受 **NB 需求疲弱、客戶接單變動、成本壓力** 影響，營收下滑風險仍在。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
