          "detailMarkdown": "## 1432 大魯閣 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026 年第一季營收較 2025 年第四季減少 36.44%，主因為商場事業出售後營收組合變動。\n- 2026 年第一季營業損失為 5,274 萬元，稅後淨損 6,262 萬元，每股盈餘為 -0.54 元。\n- 2026 年第一季 EBITDA 為 718.3 萬元。\n- 事業架構目前包含自營事業部、運動休閒事業部、不動產事業部、海外事業部。\n- 海外方面，美國市場已開出 4 家店，另有德州 San Antonio 店預計下月開幕。\n\n### 展望與成長利基\n- 美國市場將持續擴張，並以 2 萬至 3 萬平方英尺、室內複合式娛樂空間為主要展店模式。\n- 美國 San Antonio 新店將導入 Party Room 與全尺寸酒吧，作為後續海外展店的重要參考模型。\n- 日本市場預計於 9 月在千葉與宇都宮同步開出 2 家打擊場，採收購既有場地後娛樂化改造模式。\n- 建設開發案持續推進：南港都更案預計 2030 年完工；晴光都更案預計 2027 年 5 月開工、2031 年 4 月完工。\n- 公司表示未來仍將持續發展運動休閒、海外事業及台灣建設開發。\n\n### 產品、客戶與市場位置\n- 目前據點包含：台灣打擊場及保齡球館合計 14 家、遊戲愛樂園 10 家、Roller186 2 家、福湯鹽盤浴 2 家、美國度假村 1 家。\n- 2026 年 1 月已完成營業地址變更；5 月美國亞利桑那州 Gilbert 店加入營運。\n- 海外方面，美國市場已開出 4 家店，另有德州 San Antonio 店預計下月開幕。\n- 美國市場將持續擴張，並以 2 萬至 3 萬平方英尺、室內複合式娛樂空間為主要展店模式。\n- 美國 San Antonio 新店將導入 Party Room 與全尺寸酒吧，作為後續海外展店的重要參考模型。\n- 日本市場預計於 9 月在千葉與宇都宮同步開出 2 家打擊場，採收購既有場地後娛樂化改造模式。\n\n### 風險與不確定性\n- 商場事業出售後，營收基礎與產品組合已明顯改變，後續營運表現需觀察轉型成效。\n- 海外展店涉及不同市場文化、消費型態與營運模式調整，執行不確定性較高。\n- 都更案與建設開發案具長天期特性，完工時程與開發成果存在變動風險。\n- 美國與日本新據點的開幕時程、加盟/收購後整合與市場接受度，均屬未來不確定因素。\n- 未揭露更完整之財務預測、資本支出與資金來源規劃。\n- **需人工確認**：轉錄內容提及「2025 年 11 月董事會通過」及「2025/12/31 讓與基準日」，與本次法說日期（2026-07-02）時間點一致性合理，但仍建議以簡報/公告核對正式決議與交易進度。\n- **需人工確認**：轉錄中「2026 年第一季營收較 2025 年第四季減少 36.44%」屬跨季度比較口徑，請確認是否為簡報原文統計方式。\n- **需人工確認**：美國據點數量與地點敘述中，先提到「第 4 家據點 Gilbert 店」，後文又說「目前已經有 4 家店」，但同段後續列出 Katy、Mesa、Chandler、Gilbert 等，整體數量可對上，仍建議核對是否包含未單獨點名的據點。\n\n### Q&A 與管理層口氣\n- 本次摘要未擷取到明確 Q&A 或管理層口氣補充。\n\n### 評分利基點\n- 加分主因：海外展店涉及不同市場文化、消費型態與營運模式調整，執行不確定性較高。。\n- 扣分或保留：商場事業出售後，營收基礎與產品組合已明顯改變，後續營運表現需觀察轉型成效。；海外展店涉及不同市場文化、消費型態與營運模式調整，執行不確定性較高。；都更案與建設開發案具長天期特性，完工時程與開發成果存在變動風險。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
