          "detailMarkdown": "## 6658 聯策 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（51 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 公司成立於 2002 年，上市代號 6658，資本額 3.64 億元，集團員工 320+。\n- 子公司包含映利科技與頎晶科技；轉錄與簡報一致指出前者偏水平濕製程設備，後者偏 PCB 表面處理代工。\n- 簡報提到 2025 年合併營收規模較 2024 年提升，2026 Q1 營收持續成長且 EPS 明顯改善。\n- 轉錄補充稱 2025 年營收約由 2024 年的 20.8 億元成長，2026 Q1 EPS 已超越前一年度表現；**需人工確認**：簡報未提供該 20.8 億數字。\n- 股利政策方面，簡報與轉錄皆提到近三年每股現金股利維持 1.20 元左右，展現穩定回饋方向。\n- 未揭露：毛利率、營益率、淨利、現金流、接單金額與客戶集中度。\n\n### 展望與成長利基\n- 公司認為 AI Server / HPC 帶動高階 PCB、HDI 與 IC 載板升級，需求重點落在多層化、高密度、高良率與製程穩定。\n- 在設備機會上，聚焦 AOI / AVI、線寬線距量測、AI 複判、水平濕製程、在線藥水分析與清洗設備。\n- 先進封裝方面，簡報與轉錄都提到玻璃基板、CPO 載板、光電封裝與 Wafer-to-Panel 延伸製程，並強調檢測、清洗、蝕刻、金屬化與追溯管理。\n- 公司表示已透過桃園營運總部整合研發與產能，並以海外據點支援東南亞與印度市場的在地服務需求。\n- 轉錄提到部分設備解析度已從較高微米數持續提升至更高精度，並結合多光源與 AI 分析；**需人工確認**：相關解析度數字在轉錄中有多版本描述。\n\n### 產品、客戶與市場位置\n- 公司定位為「智能製造整合服務」，聚焦 PCB、半導體載板與先進封裝應用，整合濕製程、檢測與機器視覺設備。\n- 簡報主軸分為公司介紹、營運績效與營運展望，並延伸至 AI 伺服器、玻璃基板、CPO／光電封裝與半導體載具等機會。\n- 公司提到在兩岸及東南亞市場，與多數指標客戶建立長期合作關係，並透過海外據點提供在地服務。\n- 目前簡報內容以產業趨勢與產品方案說明為主，未揭露完整財務細項。\n- 未揭露：毛利率、營益率、淨利、現金流、接單金額與客戶集中度。\n- 公司認為 AI Server / HPC 帶動高階 PCB、HDI 與 IC 載板升級，需求重點落在多層化、高密度、高良率與製程穩定。\n\n### 風險與不確定性\n- 簡報免責聲明指出，營運受市場需求、產業競爭、法規、匯率與總體經濟影響，實際結果可能與預期不同。\n- 公司不提供財務預測，亦不評論特定客戶、接單金額、毛利率或未公開資訊。\n- 海外擴廠與在地服務雖為機會，但仍可能受當地供應鏈、交期與執行節奏影響。\n- 先進封裝與玻璃基板屬於新技術與驗證導入階段，量產節奏與客戶採用進度具不確定性。\n- 轉錄內容部分出現重複、口誤與名詞混用，資訊可靠度需交叉確認。\n- 「頎晶科技」在簡報中為子公司名稱；轉錄多次出現「啟晶科技」的口誤或轉錄誤差，**需人工確認**。\n- 簡報寫「近三年每股現金股利維持 1.20 元」，轉錄口語提到「1.22 元」；**需人工確認**。\n- 轉錄提及 2024 年營收 20.8 億、2025 年創高等數字，簡報未列示明細；**需人工確認**。\n\n### Q&A 與管理層口氣\n- 未揭露：毛利率、營益率、淨利、現金流、接單金額與客戶集中度。\n- 公司表示已透過桃園營運總部整合研發與產能，並以海外據點支援東南亞與印度市場的在地服務需求。\n- 公司不提供財務預測，亦不評論特定客戶、接單金額、毛利率或未公開資訊。\n- 海外擴廠與在地服務雖為機會，但仍可能受當地供應鏈、交期與執行節奏影響。\n- 轉錄末段問答內容重複且片段化，部分句子疑似多次覆寫，建議僅作方向性參考。\n\n### 評分利基點\n- 加分主因：轉錄中多次強調公司由設備代理起家，逐步延伸到自有技術、製造與系統整合。；簡報提到 2025 年合併營收規模較 2024 年提升，2026 Q1 營收持續成長且 EPS 明顯改善。；轉錄補充稱 2025 年營收約由 2024 年的 20.8 億元成長，2026 Q1 EPS 已超越前一年度表現；**需人工確認**：簡報未提供該 20.8 億數字。。\n- 扣分或保留：簡報免責聲明指出，營運受市場需求、產業競爭、法規、匯率與總體經濟影響，實際結果可能與預期不同。；公司不提供財務預測，亦不評論特定客戶、接單金額、毛利率或未公開資訊。；海外擴廠與在地服務雖為機會，但仍可能受當地供應鏈、交期與執行節奏影響。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
