          "detailMarkdown": "## 6257 矽格 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 合併營收 52.9 億元，年增約 13%。\n- 2026Q1 本期淨利 11.2 億元，年增 29.3%；歸屬母公司淨利 10.1 億元，EPS 2.1 元。\n- Q1 毛利率約接近 32%，營業費用率約 9% 左右，營運表現較去年同期提升。\n- 資產負債表顯示不動產、廠房及設備增加，負債比約 43%~44%，流動比率由 169% 提升至 185%。\n- 1~5 月合併營收 92.16 億元，年增 17%；1、3、4、5 月營收皆創歷史新高，2 月受春節影響較低。\n\n### 展望與成長利基\n- 下半年成長動能以 AI ASIC、矽光子、高速運算、AI Connectivity 為主，智慧手機與網通也有支撐。\n- 管理層預期矽光相關多數專案將於今年下半年至明年陸續放量，明年貢獻可能更明顯。\n- 公司將持續推進 3A 策略：Advanced Test Technology、Automation、AI Factory。\n- 湖口二廠預計 7 月起開始量產；矽格中心三廠預計提前至 2026Q4 完工。\n- 2026 年 5 月董事會通過追加資本支出 28.22 億元，全年資本支出合計 88 億元，集團資本支出合計 186 億元。\n\n### 產品、客戶與市場位置\n- 管理層指出，AI ASIC、AI Connectivity、矽光子、高速運算相關需求為主要成長來源。\n- 公司提到擴廠與設備追加持續推進，資本支出上修，並以新廠投產支應客戶需求。\n- Q&A 顯示現階段產能偏滿載，部分新廠產能已被客戶預訂。\n- 會中多次提及測試價格調整、AI 應用帶動高階測試需求升溫。\n- 下半年成長動能以 AI ASIC、矽光子、高速運算、AI Connectivity 為主，智慧手機與網通也有支撐。\n- 公司將持續推進 3A 策略：Advanced Test Technology、Automation、AI Factory。\n\n### 風險與不確定性\n- 管理層提到消費性產品成長動能相對承壓，部分終端市場仍偏平淡。\n- 設備交期長，對營收認列節奏與擴產進度有影響。\n- 自由現金流可能因擴廠與資本支出增加而短期承壓。\n- 部分產品與客戶資訊未明確揭露，實際需求與放量時點仍有不確定性。\n- 測試價格調整雖已進行，但幅度與後續效益仍受市場環境影響。\n- **需人工確認**：轉錄中出現「車用跟醫療占比從 7% 滑落到 62%」；此數字顯然不合理，疑似口誤，需與簡報或財報原文核對。\n- **需人工確認**：轉錄中多處提到「矽動氣電容／矽電容」，用語不一致，疑似同一產品別不同口誤，需確認正式專有名詞。\n- **需人工確認**：轉錄提及「AIASIC 矽光子高速運算」占比為 2~3%，與後續問答對 23% 的 AI 相關占比敘述可能指涉範圍不同，需釐清分類基礎。\n\n### Q&A 與管理層口氣\n- 目前產能利用率約 70%~80%，新廠完成後單一廠區產能可提升約 10%~20%。\n- 目前測試價格持續調漲，係以每小時機台測試費用調整為主。\n- AI ASIC 相關業務已見新客戶加入；矽光產品今年下半年與明年均有機會持續貢獻。\n- ASIC 相關業務除 Final Test 外，亦涵蓋 CP、Binning、SLT；矽光目前以 CP 與 Final Test 為主。\n- AOI 瑕疵檢測主要為外購硬體搭配公司自研 AI 軟體；部分客戶採「扛機」模式。\n- Q&A 中提到 CPU、CSP 客戶、品牌、特定封裝技術等細節，多數未進一步揭露。\n\n### 評分利基點\n- 加分主因：管理層指出，AI ASIC、AI Connectivity、矽光子、高速運算相關需求為主要成長來源。；公司提到擴廠與設備追加持續推進，資本支出上修，並以新廠投產支應客戶需求。；會中多次提及測試價格調整、AI 應用帶動高階測試需求升溫。。\n- 扣分或保留：管理層提到消費性產品成長動能相對承壓，部分終端市場仍偏平淡。；設備交期長，對營收認列節奏與擴產進度有影響。；自由現金流可能因擴廠與資本支出增加而短期承壓。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
