          "detailMarkdown": "## 7730 暉盛-創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026 年第一季營收 **NT$92,232 仟元**，年增 **10.9%**。\n- 第一季毛利率 **46%**，較去年同期提升 **4 個百分點**。\n- 第一季營業利益 **NT$11,150 仟元**，較去年同期轉盈。\n- 第一季 EPS **0.37 元**，年增 **363%**。\n- 簡報表示成本與費用率改善，且高單價 RIE 與高階設備占比提升，帶動獲利結構優化。\n\n### 展望與成長利基\n- 2026 年訂單動能以 **49 件（Confirmed 35、LOI 14）** 為主，後續觀察 LOI 轉單情況。\n- 簡報指出第二季後交付集中，對全年營運能見度具支撐。\n- 技術路線圖顯示 2025-2027 年聚焦 **Hybrid Bonding、Glass TGV、Chiplet、Glass Core** 等應用。\n- 公司認為 AI 伺服器與高階封裝需求，將持續推動 ABF/BT、玻璃基板等製程設備需求。\n- 亦提到維修服務收入隨安裝基礎擴大而成長，作為較穩定的營運來源之一。\n\n### 產品、客戶與市場位置\n- 公司定位於**電漿乾式製程設備**，聚焦先進封裝與半導體製程應用。\n- 簡報主軸圍繞 **AI/HPC、ABF/BT、FOPLP/FOWLP、Glass Substrate/TGV、Hybrid Bonding** 等先進封裝趨勢。\n- 簡報提及多項技術驗證、客戶導入與新製程路線圖，顯示產品組合持續擴展。\n- 公司認為 AI 伺服器與高階封裝需求，將持續推動 ABF/BT、玻璃基板等製程設備需求。\n- LOI 是否如期轉為正式訂單，仍取決於客戶驗證與量產導入進度。\n- 先進製程與客戶開發高度集中於特定市場與應用，需求波動可能影響訂單節奏。\n\n### 風險與不確定性\n- LOI 是否如期轉為正式訂單，仍取決於客戶驗證與量產導入進度。\n- 先進封裝應用的驗證週期長，簡報提及可能達 **6-18 個月**。\n- 先進製程與客戶開發高度集中於特定市場與應用，需求波動可能影響訂單節奏。\n- 簡報亦提及技術轉換與量產時點存在不確定性，未保證未來財務表現。\n- 對 AI/HPC 與高階封裝景氣的依賴度高，外部資本支出變化可能影響需求。\n- **需人工確認**：轉錄內容未提供，以下數字皆以英文簡報為主，無法交叉比對語音一致性。\n- **需人工確認**：中文 PDF 多頁出現大量「暉/年」字樣異常，疑似 OCR 或轉錄失真，建議以英文版簡報為準。\n- **需人工確認**：簡報中提及「2026 年上半年」與「Q1 2026」之敘述一致，但若語音有提到上半年整體財務數字，需再核對。\n\n### Q&A 與管理層口氣\n- **語音轉錄未提供**，未見可整理之問答內容。\n- 簡報列示客戶驗證、訂單結構與市場分布，但未見完整逐題 Q&A。\n- MOPS 擇要僅說明受邀參加創新板公司法人說明會，未揭露其他會議紀錄。\n- 簡報含免責聲明，強調資料來自技術與財務彙整，且不構成投資建議。\n\n### 評分利基點\n- 加分主因：公司強調「**Dry Only**」策略，以乾式電漿取代部分傳統濕製程，主打精度、環保與一致性。；第一季毛利率 **46%**，較去年同期提升 **4 個百分點**。；簡報表示成本與費用率改善，且高單價 RIE 與高階設備占比提升，帶動獲利結構優化。。\n- 扣分或保留：LOI 是否如期轉為正式訂單，仍取決於客戶驗證與量產導入進度。；先進封裝應用的驗證週期長，簡報提及可能達 **6-18 個月**。；先進製程與客戶開發高度集中於特定市場與應用，需求波動可能影響訂單節奏。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
