          "detailMarkdown": "## 7777 能率亞洲 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026/Q1 營業收入為 **-39,298 千元**，較 2025/Q1 的 **-58,506 千元**改善；稅後淨損為 **-45,382 千元**，EPS 為 **-0.25 元**。\n- 簡報註明，營業收入主要來自**投資標的之評價損益（含已實現及未實現）**，其他綜合損益則反映投資標的未實現評價與所得稅影響。\n- 2026/Q1 透過損益按公允價值衡量之金融資產為 **1,124,682 千元**，較 2025/Q1 的 **758,095 千元**增加；透過其他綜合損益按公允價值衡量之金融資產為 **401,682 千元**。\n- 資本額由 2025/Q1 的 **1,675,000 千元**增至 2026/Q1 的 **1,825,000 千元**。\n- 除權息資訊：2025 盈餘擬配發**現金股利 0.025 元**、**股票股利 0.225 元**，除息／除權基準日為 **2026/7/1**（簡報文字與口頭說明日期有差異，見交叉核對註記）。\n\n### 展望與成長利基\n- 公司將持續聚焦 **數位轉型、AI 應用、機器人、半導體、生技** 等主題投資。\n- 簡報指出，未來將深化與 **NVIDIA 生態**相關的布局，並延伸至智慧城市、智慧工廠、智慧交通與實體 AI 應用。\n- 會中提到 **Agility Robotics**、**Linker Vision** 為 2026 年重點布局，並希望透過投後協助推進亞洲市場與策略合作。\n- **大易橙科技**被描述為由二次配電延伸至 MEP 與電力統包，未來營運展望持續提升，並規劃現金增資。\n- **雷文虎克**則聚焦益生菌與代謝相關產品，簡報提及其臨床實證與授權洽談進展。\n\n### 產品、客戶與市場位置\n- 公司定位為**創業投資業**，並強調同時具備**台灣與日本**業務資源，投資主題集中在數位轉型、AI／機器人、半導體與生技等領域。\n- 簡報與口頭說明都強調，公司將資源放在**未來高成長標的**，並透過投後協助、資本市場規劃與策略合作放大投資價值。\n- 公司將持續聚焦 **數位轉型、AI 應用、機器人、半導體、生技** 等主題投資。\n- 簡報指出，未來將深化與 **NVIDIA 生態**相關的布局，並延伸至智慧城市、智慧工廠、智慧交通與實體 AI 應用。\n- 會中提到 **Agility Robotics**、**Linker Vision** 為 2026 年重點布局，並希望透過投後協助推進亞洲市場與策略合作。\n- **雷文虎克**則聚焦益生菌與代謝相關產品，簡報提及其臨床實證與授權洽談進展。\n\n### 風險與不確定性\n- 簡報明確揭露：前瞻性敘述受**風險、不確定性與推論**影響，實際結果可能與預期不同。\n- 投資標的多屬**新創或成長型公司**，其估值與市場認同度可能較高波動，且部分標的尚未進入評價或尚未獲利。\n- 口頭說明提到，部分軟體／AI 公司以 **PB/PS** 評價居多，若資本市場接受度不足，估值可能出現變化。\n- 半導體供應鏈與回收／化學材料布局涉及**認證、開工進度、客戶導入**等變數。\n- 簡報亦提及投資案件受總體環境影響，例如 AI、機器人、地緣政治與市場修正等因素。\n- **需人工確認：** 簡報頁面寫「**於 2025年12月22日 掛牌**」，但日期上與本次 2026/06/17 法說會時間序不一致，且需確認是否為**2025/12/22**或其他日期。\n- **需人工確認：** 簡報第 7 頁寫「**預計於 2026 年 6 月 25 日除權息**」，第 4 頁則寫「**除息基準日 / 除權基準日 2026/7/1**」，兩者日期不一致。\n- **需人工確認：** 語音轉錄中出現「**0.0225 的股票補利**」等說法，與簡報中的 **股票股利 0.225 元、現金股利 0.025 元**一致性需再核對。\n\n### Q&A 與管理層口氣\n- 會中有詢問**評價基礎**，回覆為：上市櫃公司採用**最近月收盤價**，新櫃公司則視流動性與可得資料決定是否採用新櫃價格或改以市場法估值。\n- 口頭說明提到，公司將持續協助投資標的做**海外策略合作、台灣供應鏈串接、下一輪增資規劃**。\n- 管理層也提到，創投的特性是投資週期長，成功案例需要較長時間培育，並非短期可完全反映。\n- 會中多次提及與 **NVIDIA、Cisco、AT&T、Toyota** 等國際夥伴的合作或洽談進展。\n- 其他提問與追問內容未完整揭露。\n\n### 評分利基點\n- 加分主因：公司定位為**創業投資業**，並強調同時具備**台灣與日本**業務資源，投資主題集中在數位轉型、AI／機器人、半導體與生技等領域。；簡報與口頭說明都強調，公司將資源放在**未來高成長標的**，並透過投後協助、資本市場規劃與策略合作放大投資價值。；2026/Q1 營業收入為 **-39,298 千元**，較 2025/Q1 的 **-58,506 千元**改善；稅後淨損為 **-45,382 千元**，EPS 為 **-0.25 元**。。\n- 扣分或保留：簡報明確揭露：前瞻性敘述受**風險、不確定性與推論**影響，實際結果可能與預期不同。；投資標的多屬**新創或成長型公司**，其估值與市場認同度可能較高波動，且部分標的尚未進入評價或尚未獲利。；口頭說明提到，部分軟體／AI 公司以 **PB/PS** 評價居多，若資本市場接受度不足，估值可能出現變化。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
