          "detailMarkdown": "## 6272 驊陞 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（44 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 0、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 公司主要業務為智能電子零組件與車用電子零組件。\n- 主要據點包含台灣、中國昆山與東莞、越南及美國等地，並已納入越南廠量產與東莞新廠規劃。\n- FY26 Q1 合併營收為新台幣 704,351 仟元，稅後淨利 10,815 仟元，EPS 0.13 元。\n- FY26 Q1 毛利率 21.0%，營業利益率 2.5%，EBITDA 56,009 仟元。\n- 最近三年度財務比率顯示，FY25 負債比 51.41%，流動比率 177.36%，速動比率 129.80%。\n\n### 展望與成長利基\n- CCDC 以 AI Server 與 HPC 平台高速互連市場為切入方向，產品涵蓋 PCIe 6.0/7.0、MCIO、Oculink、U.2/U.3、SFP/QSFP/OSFP 等連接方案。\n- ATTD 聚焦 AI 高功耗熱管理，產品頁面列示 CPU Tower Cooler、GPU Heat Sink、顯示卡散熱模組。\n- ICPS 鎖定智慧製造與工業互連市場，應用場景包含機器人、Edge AI、工業通訊控制、鐵路運輸與寬頻無線接取。\n- 越南廠已於 2025 年 5 月完工、6 月正式營運；東莞洪梅新廠預計 2026 年正式營運。\n- 2026 年 3 月成立創新發展研發中心。\n\n### 產品、客戶與市場位置\n- 公司於 2026/06/15 舉行法人說明會，主題為營運概況與產品/佈局進展。\n- 會議架構分為公司概況、財務資訊、產品與佈局計畫、問答交流。\n- 長期願景為打造電子零組件與電子產品設計及智能製造的高競爭力服務公司。\n- 主要據點包含台灣、中國昆山與東莞、越南及美國等地，並已納入越南廠量產與東莞新廠規劃。\n- CCDC 以 AI Server 與 HPC 平台高速互連市場為切入方向，產品涵蓋 PCIe 6.0/7.0、MCIO、Oculink、U.2/U.3、SFP/QSFP/OSFP 等連接方案。\n- ATTD 聚焦 AI 高功耗熱管理，產品頁面列示 CPU Tower Cooler、GPU Heat Sink、顯示卡散熱模組。\n\n### 風險與不確定性\n- 簡報載明含有前瞻性陳述，實際營運、財務與產業發展可能與預期有重大差異。\n- 公司聲明簡報內容僅反映截至會談當日狀況，後續不承諾即時更新。\n- 簡報未揭露本次法說會中具體市場風險、客戶集中度或供應鏈風險細項。\n- 未揭露原物料、匯率、關稅或產能爬坡對營運的影響程度。\n- 未揭露 Q&A 中是否有特定風險議題被追問。\n- **需人工確認**：中文簡報第 5 頁標示「上市日期 2025/12/22」，與 MOPS 摘要、以及簡報第 6 頁所示「12月驊陞科技正式掛牌上市」的時間描述，可能涉及年份或表述口徑差異。\n- **需人工確認**：中英文簡報皆提到 2026 年 3 月成立「創新發展研發中心」，但中文第 8 頁與英文第 8 頁的部門/人名編排略有差異，需確認是否為翻譯排版差異。\n- **需人工確認**：第 11、12 頁的年度財務比較中，FY25/FY24/FY23 的基期與欄位順序在中英文版一致，但部分數字呈現格式與標題敘述略有不同，建議以原始財報或 MOPS 為準再核對。\n\n### Q&A 與管理層口氣\n- 會議架構分為公司概況、財務資訊、產品與佈局計畫、問答交流。\n- FY26 Q1 毛利率 21.0%，營業利益率 2.5%，EBITDA 56,009 仟元。\n- 簡報未揭露本次法說會中具體市場風險、客戶集中度或供應鏈風險細項。\n- 未揭露原物料、匯率、關稅或產能爬坡對營運的影響程度。\n- 未揭露 Q&A 中是否有特定風險議題被追問。\n\n### 評分利基點\n- 加分主因：簡報主軸聚焦三大新事業部：CCDC 高速傳輸、ATTD 先進熱傳、ICPS 智慧工控。；長期願景為打造電子零組件與電子產品設計及智能製造的高競爭力服務公司。；主要據點包含台灣、中國昆山與東莞、越南及美國等地，並已納入越南廠量產與東莞新廠規劃。。\n- 扣分或保留：簡報載明含有前瞻性陳述，實際營運、財務與產業發展可能與預期有重大差異。；公司聲明簡報內容僅反映截至會談當日狀況，後續不承諾即時更新。；簡報未揭露本次法說會中具體市場風險、客戶集中度或供應鏈風險細項。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
